import re
import spacy
import dateparser
from datetime import datetime
from typing import Optional
from bs4 import BeautifulSoup

from .spacy_model import nlp

# Load SpaCy model (ensure you have "en_core_web_sm" or similar installed)
# nlp = spacy.load("en_core_web_sm")

# Configure logging to write to a file
LOG_FILE = "get_date_from_element.log"

def log_to_file(message: str):
    """Helper function to log messages to a file with line spacing."""
    with open(LOG_FILE, "a") as log_file:
        log_file.write(message + "\n\n")

def get_date_from_element(html_snippet: str) -> str:
    log_to_file("============================================================")
    log_to_file(f"Input HTML Snippet:\n{html_snippet}")
    log_to_file("============================================================")
    
    """
    Combined approach:
      1) Try extracting a full date (YYYY-MM-DD) via regex + spacy + dateparser.
      2) If that fails, fallback to partial-date logic that handles months, years, etc.
      
    Returns one of: "YYYY-MM-DD", "YYYY-MM", "YYYY", or "Null".
    """

    # 1) Strip HTML to get plain text
    text = _extract_text(html_snippet)

    dt_full = _extract_complete_date_spacy_regex(text)
    if dt_full:
        # If we indeed found day/month/year, return "YYYY-MM-DD"
        # But let's confirm the snippet actually contained day and month 
        # (not just a guess). We'll do a quick check with day/month detection:
        has_day = _text_has_day(text)
        has_month = _text_has_month(text)
        if has_day and has_month:
            return f"{dt_full.year:04d}-{dt_full.month:02d}-{dt_full.day:02d}"
    
    # 3) If we don't have a confirmed full date, do partial fallback
    partial_date_str = _extract_partial_date(text)
    return partial_date_str

# -------------------------------------------------------------------------
#    SPACY + REGEX + DATEPARSER FOR FULL-DATE DETECTION
# -------------------------------------------------------------------------
def _extract_complete_date_spacy_regex(text: str) -> Optional[datetime]:
    """
    Use a combination of:
      - A direct regex for 'MMM DD, YYYY 9am EDT' patterns
      - Spacy NER (entities labeled DATE)
      - dateparser to parse the extracted string
    If a valid date with day/month/year is found, return a datetime object.
    Otherwise, return None.
    """

    # 1) Regex for "Sep 05, 2024 10:20am EDT" style
    date_pattern = r'\b([A-Za-z]{3}\s\d{1,2},\s\d{4}(?:\s\d{1,2}:\d{2}[ap]m)?\s?(?:[A-Z]{2,4})?)'
    match = re.search(date_pattern, text)
    if match:
        extracted_date_str = match.group(0)
        parsed = dateparser.parse(extracted_date_str)
        if parsed:
            # We found a date with day/month/year
            return parsed

    # 2) If regex not found, fallback to spacy NER for DATE entities
    doc = nlp(text)
    date_entities = [ent.text for ent in doc.ents if ent.label_ == "DATE"]

    # We can parse each date entity with dateparser and return 
    # the first that yields a day, month, year
    for date_str in date_entities:
        parsed = dateparser.parse(date_str)
        if parsed:
            # We'll check if it truly has day/month
            # but let's just return the first parse for now
            return parsed

    return None

# -------------------------------------------------------------------------
#    PARTIAL-DATE FALLBACK: QUARTERS -> YEAR, THEN DETECT EXACT FORMAT
# -------------------------------------------------------------------------
def _extract_partial_date(text: str) -> str:
    """
    Fallback logic to handle partial mentions:
      1) Remove references to Q1/Q2 -> keep just the year
      2) Try dateparser. If it doesn't yield a real date, see if we have a year.
      3) If we do parse, check if snippet truly has day, month, or only year.
    """
    # Remove quarter references
    text = _remove_quarter_references(text)

    # If no digits, return "Null"
    if not re.search(r"\d", text):
        return "Null"

    # Attempt parse
    parsed = dateparser.parse(text)
    if not parsed:
        # Maybe there's a single year?
        return _extract_year_only(text)

    has_day = _text_has_day(text)
    has_month = _text_has_month(text)
    if parsed.year and has_month and has_day:
        return f"{parsed.year:04d}-{parsed.month:02d}-{parsed.day:02d}"
    elif parsed.year and has_month:
        return f"{parsed.year:04d}-{parsed.month:02d}"
    elif parsed.year:
        return f"{parsed.year:04d}"
    else:
        return "Null"

# -------------------------------------------------------------------------
#    HELPERS
# -------------------------------------------------------------------------
def _extract_text(html_snippet: str) -> str:
    """Extracts visible text from HTML."""
    soup = BeautifulSoup(html_snippet, 'html.parser')
    return soup.get_text(separator=' ', strip=True)

def _remove_quarter_references(text: str) -> str:
    """Replace 'Q2 2024', 'Quarter 3 2025' etc. with just '2024', '2025'."""
    quarter_regex = re.compile(r"\b(?:Q[1-4]|Quarter\s*\d)[^\d]*(\d{4})\b", re.IGNORECASE)
    return quarter_regex.sub(r"\1", text)

def _extract_year_only(text: str) -> str:
    match = re.search(r"\b(20\d{2}|19\d{2})\b", text)
    if match:
        return match.group(1)
    return "Null"

def _text_has_day(text: str) -> bool:
    """
    Check if the text specifically suggests a day-of-month
    (like '01', '1st', '28,' '31 ', etc.)
    """
    day_pattern = re.compile(r"\b(3[01]|[12]\d|0?[1-9])(st|nd|rd|th)?\b")
    return bool(day_pattern.search(text))

def _text_has_month(text: str) -> bool:
    """
    Check if the text specifically suggests a month 
    (Jan/January/03, or something like "Aug 2023") 
    to ensure we have a real month mention.
    """
    month_pattern = re.compile(
        r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)"
        r"|([1-9]|0[1-9]|1[0-2])\b",  # stand-alone number in [1..12]
        re.IGNORECASE
    )
    return bool(month_pattern.search(text))


